function sql(value) {
  if (value === undefined || value === null || String(value).trim() === '') return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}
function sqlJson(value) { return sql(JSON.stringify(value ?? {})) + '::jsonb'; }
const body = $json.body || $json;
const publicationJobId = String(body.publicationJobId || body.publication_job_id || '').trim();
const failedStep = String(body.failedStep || body.failed_step || '').trim();
const errorMessage = String(body.errorMessage || body.error_message || body.error || '').trim();
const technicalDetails = body.technicalDetails && typeof body.technicalDetails === 'object' ? body.technicalDetails : {};
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const retryableSteps = new Set(['generate-brief', 'generate-prompt-pack', 'generate-images', 'generate-copy-pack']);
if (!uuidRegex.test(publicationJobId)) {
  return [{ json: { query: "SELECT false AS ok, 'publicationJobId is required' AS error;" } }];
}
if (!failedStep || !errorMessage) {
  return [{ json: { query: "SELECT false AS ok, 'failedStep and errorMessage are required' AS error;" } }];
}
const retryable = retryableSteps.has(failedStep);
const query = `
CREATE TABLE IF NOT EXISTS publication_job_events (
  event_id text PRIMARY KEY DEFAULT md5(random()::text || clock_timestamp()::text),
  publication_job_id uuid NOT NULL,
  event_type text NOT NULL,
  event_label text NOT NULL,
  event_status text NOT NULL DEFAULT 'completed',
  event_payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  error_message text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_publication_job_events_job_created
  ON publication_job_events (publication_job_id, created_at);
WITH job AS (
  SELECT *
  FROM publication_jobs
  WHERE publication_job_id = ${sql(publicationJobId)}::uuid
  LIMIT 1
), updated AS (
  UPDATE publication_jobs pj
  SET
    status = 'failed',
    error_message = ${sql(errorMessage)},
    updated_at = now(),
    metadata = COALESCE(pj.metadata, '{}'::jsonb) || jsonb_build_object(
      'lastError', jsonb_build_object(
        'failedStep', ${sql(failedStep)},
        'message', ${sql(errorMessage)},
        'previousStatus', (SELECT status FROM job),
        'retryable', ${retryable ? 'true' : 'false'},
        'recordedAt', now(),
        'technicalDetails', ${sqlJson(technicalDetails)}
      )
    )
  WHERE pj.publication_job_id = ${sql(publicationJobId)}::uuid
    AND EXISTS (SELECT 1 FROM job)
  RETURNING pj.*
), event AS (
  INSERT INTO publication_job_events (
    publication_job_id,
    event_type,
    event_label,
    event_status,
    event_payload,
    error_message,
    created_at
  )
  SELECT
    publication_job_id,
    'step-failed',
    'Publication step failed',
    'failed',
    jsonb_build_object('failedStep', ${sql(failedStep)}, 'previousStatus', (SELECT status FROM job), 'retryable', ${retryable ? 'true' : 'false'}, 'technicalDetails', ${sqlJson(technicalDetails)}),
    ${sql(errorMessage)},
    now()
  FROM updated
  RETURNING event_id
)
SELECT
  CASE WHEN EXISTS (SELECT 1 FROM updated) THEN true ELSE false END AS ok,
  CASE WHEN EXISTS (SELECT 1 FROM updated) THEN NULL ELSE 'Publication job not found' END AS error,
  (SELECT publication_job_id FROM updated) AS "publicationJobId",
  (SELECT avatar FROM updated) AS avatar,
  (SELECT scene FROM updated) AS scene,
  (SELECT format FROM updated) AS format,
  (SELECT objective FROM updated) AS objective,
  (SELECT business_profile FROM updated) AS "businessProfile",
  (SELECT asset_type FROM updated) AS "assetType",
  (SELECT status FROM updated) AS status,
  (SELECT brief FROM updated) AS brief,
  (SELECT prompt_pack FROM updated) AS "promptPack",
  (SELECT publishing_pack FROM updated) AS "publishingPack",
  (SELECT metadata->'publishingExport' FROM updated) AS "publishingExport",
  (SELECT metadata->'publishedRecord' FROM updated) AS "publishedRecord",
  (SELECT error_message FROM updated) AS "errorMessage",
  (SELECT created_at FROM updated) AS "createdAt",
  (SELECT updated_at FROM updated) AS "updatedAt";
`;
return [{ json: { query } }];

function parse(value, fallback) {
  if (value == null) return fallback;
  if (typeof value === 'string') { try { return JSON.parse(value); } catch { return fallback; } }
  return value;
}
const row = $input.first()?.json || {};
if (row.ok === false || row.ok === 'f') {
  return [{ json: { ok: false, recorded: false, error: row.error || 'Publication job error was not recorded.' } }];
}
return [{ json: { ok: true, recorded: true, job: {
  publicationJobId: row.publicationJobId,
  avatar: row.avatar,
  scene: row.scene,
  format: row.format,
  objective: row.objective,
  businessProfile: row.businessProfile,
  assetType: row.assetType,
  status: row.status,
  brief: parse(row.brief, null),
  promptPack: parse(row.promptPack, null),
  publishingPack: parse(row.publishingPack, null),
  publishingExport: parse(row.publishingExport, null),
  publishedRecord: parse(row.publishedRecord, null),
  errorMessage: row.errorMessage,
  createdAt: row.createdAt,
  updatedAt: row.updatedAt
} } }];
